// product, with NO grant yet. The doujins migrate moved these payments as
// source-of-truth (rail=solana, amount>0) but no longer derives their membership
// entitlement — derive-1 materializes grant + window [purchased_at,
// expiration_rfc3339). Distinct from the general `derive.grant.missing` (payments)
// ADMIN finding: the explicit stored expiration makes the window unambiguous, so
// this migrated cohort auto-repairs instead of waiting for an operator.
func (q *Queries) ListUngrantedWalletPayments(ctx context.Context, arg ListUngrantedWalletPaymentsParams) ([]ListUngrantedWalletPaymentsRow, error) {
	rows, err := q.db.Query(ctx, listUngrantedWalletPayments, arg.MerchantID, arg.CustomerID, arg.ScanSince)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	var items []ListUngrantedWalletPaymentsRow
	for rows.Next() {
		var i ListUngrantedWalletPaymentsRow
		if err := rows.Scan(
			&i.ID,
			&i.CustomerID,
			&i.PurchasedAt,
			&i.ExpiresAt,
			&i.EntitlementsSpec,
		); err != nil {
			return nil, err
		}
		items = append(items, i)
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return items, nil
}

const listUnretractedTerminations = `-- name: ListUnretractedTerminations :many
SELECT g.id, g.merchant_id, g.customer_id, g.product_id, g.kind, g.source_type, g.source_id, g.payment_id, g.event, g.supersedes_id, g.spec_snapshot, g.starts_at, g.ends_at, g.amount, g.currency, g.reason, g.created_at FROM openrails.grants g
WHERE g.merchant_id = $1::uuid
  AND ($2::uuid IS NULL OR g.customer_id = $2::uuid)
  AND g.event = 'grant'
  AND EXISTS (
      SELECT 1 FROM openrails.grants t
      WHERE t.merchant_id = g.merchant_id AND t.supersedes_id = g.id
        AND t.event IN ('revoke', 'expire', 'supersede')
  )
  AND (
    (g.kind = 'entitlement' AND EXISTS (
        SELECT 1 FROM openrails.entitlements e
        WHERE e.merchant_id = g.merchant_id AND e.grant_id = g.id
          AND e.revoked_at IS NULL AND e.deleted_at IS NULL))
    OR
    (g.kind = 'credit' AND (
        g.amount - COALESCE((
            SELECT SUM(t.amount) FROM openrails.ledger_transfers t
            WHERE t.merchant_id = g.merchant_id AND t.grant_id = g.id
              AND t.transfer_type IN ('credit_spend', 'credit_expire', 'credit_revoke')
        ), 0)) > 0)
  )
ORDER BY g.created_at
`

type ListUnretractedTerminationsParams struct {
	MerchantID uuid.UUID
	CustomerID *uuid.UUID
}

// #511/#575 DERIVE `derive.grant_effect.excess` as a single set query: TERMINATED
// grants whose derived effect is still live (a revoke/expire recorded but its
// retraction never propagated). Mirrors Go IsGrantTerminated + effectStillLive —
// entitlement: a non-revoked, non-deleted entitlement row; credit: lot remainder
// (amount − spend/expire/revoke transfers) > 0. customer_id nullable: NULL =
// merchant-wide sweep. Repair = MaterializeGrant (retracts) — idempotent.
func (q *Queries) ListUnretractedTerminations(ctx context.Context, arg ListUnretractedTerminationsParams) ([]OpenrailsGrant, error) {
	rows, err := q.db.Query(ctx, listUnretractedTerminations, arg.MerchantID, arg.CustomerID)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	var items []OpenrailsGrant
	for rows.Next() {
		var i OpenrailsGrant
		if err := rows.Scan(
			&i.ID,
			&i.MerchantID,
			&i.CustomerID,
			&i.ProductID,
			&i.Kind,
			&i.SourceType,
			&i.SourceID,
			&i.PaymentID,
			&i.Event,
			&i.SupersedesID,
			&i.SpecSnapshot,
			&i.StartsAt,
			&i.EndsAt,
			&i.Amount,
			&i.Currency,
			&i.Reason,
			&i.CreatedAt,
		); err != nil {
			return nil, err
		}
		items = append(items, i)
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return items, nil
}

const productUsageLimitBindingExistsForGrant = `-- name: ProductUsageLimitBindingExistsForGrant :one
SELECT EXISTS (
    SELECT 1 FROM openrails.product_usage_limit_bindings
    WHERE merchant_id = $1::uuid
      AND grant_id = $2::uuid
      AND usage_limit_key = $3::text
) AS exists
`

type ProductUsageLimitBindingExistsForGrantParams struct {
	MerchantID    uuid.UUID
	GrantID       uuid.UUID
	UsageLimitKey string
}

func (q *Queries) ProductUsageLimitBindingExistsForGrant(ctx context.Context, arg ProductUsageLimitBindingExistsForGrantParams) (bool, error) {
	row := q.db.QueryRow(ctx, productUsageLimitBindingExistsForGrant, arg.MerchantID, arg.GrantID, arg.UsageLimitKey)
	var exists bool
	err := row.Scan(&exists)
	return exists, err
}

const revokeEntitlementsByGrant = `-- name: RevokeEntitlementsByGrant :execrows
UPDATE openrails.entitlements
SET revoked_at = $1::timestamptz,
    revoke_reason = $2::text,
    updated_at = now()
WHERE merchant_id = $3::uuid
  AND grant_id = $4::uuid
  AND revoked_at IS NULL AND deleted_at IS NULL
`

type RevokeEntitlementsByGrantParams struct {
	RevokedAt    time.Time
	RevokeReason string
	MerchantID   uuid.UUID
	GrantID      uuid.UUID
}

func (q *Queries) RevokeEntitlementsByGrant(ctx context.Context, arg RevokeEntitlementsByGrantParams) (int64, error) {
	result, err := q.db.Exec(ctx, revokeEntitlementsByGrant,
		arg.RevokedAt,
		arg.RevokeReason,
		arg.MerchantID,
		arg.GrantID,
	)
	if err != nil {
		return 0, err
	}
	return result.RowsAffected(), nil
}

const revokeProductUsageLimitBindingsByGrant = `-- name: RevokeProductUsageLimitBindingsByGrant :exec
UPDATE openrails.product_usage_limit_bindings
SET revoked_at = $1::timestamptz,
    updated_at = now(),
    policy_version = policy_version + 1
WHERE merchant_id = $2::uuid
  AND grant_id = $3::uuid
  AND revoked_at IS NULL
`

type RevokeProductUsageLimitBindingsByGrantParams struct {
	RevokedAt  time.Time
	MerchantID uuid.UUID
	GrantID    uuid.UUID
}

func (q *Queries) RevokeProductUsageLimitBindingsByGrant(ctx context.Context, arg RevokeProductUsageLimitBindingsByGrantParams) error {
	_, err := q.db.Exec(ctx, revokeProductUsageLimitBindingsByGrant, arg.RevokedAt, arg.MerchantID, arg.GrantID)
	return err
}

const sumCreditGrants = `-- name: SumCreditGrants :one
SELECT COALESCE(SUM(amount), 0)::bigint
FROM openrails.grants
WHERE merchant_id = $1::uuid
  AND customer_id = $2::uuid
  AND currency = $3::text
  AND kind = 'credit' AND event = 'grant'
`

type SumCreditGrantsParams struct {
	MerchantID uuid.UUID
	CustomerID uuid.UUID
	Currency   string
}

// SumCreditGrants: cumulative credits granted to a customer in one currency (the
// "amount paid / trust signal" that graduates the tier). Replaces SumMoneyDeposits.
func (q *Queries) SumCreditGrants(ctx context.Context, arg SumCreditGrantsParams) (int64, error) {
	row := q.db.QueryRow(ctx, sumCreditGrants, arg.MerchantID, arg.CustomerID, arg.Currency)
	var column_1 int64
	err := row.Scan(&column_1)
	return column_1, err
}
